import { mkdir, readFile, writeFile } from "node:fs/promises";
const html = await readFile(
  new URL("../dist/index.html", import.meta.url),
  "utf8",
);
if (!html.includes('id="root"') || !html.includes("/assets/"))
  throw Error("Production HTML template is missing its root or built assets.");
await mkdir(new URL("../generated/", import.meta.url), { recursive: true });
await writeFile(
  new URL("../generated/site-template.mjs", import.meta.url),
  "// Generated by npm run build. Bundled with server adapters; never fetched from the site itself.\nexport default " +
    JSON.stringify(html) +
    ";\n",
);
console.log("Production template embedded for Netlify and Vercel functions.");
